starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "lb_arn" {
  description = "Input variable lb_arn."
  type        = string
}

variable "target_group_arn" {
  description = "Input variable target_group_arn."
  type        = string
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_lb_listener" "this" {
  # TODO - Complete the aws_lb_listener resource.
  # Add the arguments and nested blocks required for aws_lb_listener.
}
